body.script:
//
(function(){
  'use strict';
  var d = document, root = d.documentElement, body = d.body;
  var $ = function(s, c){ return (c || d).querySelector(s); };
  var $$ = function(s, c){ return Array.prototype.slice.call((c || d).querySelectorAll(s)); };

  /* Year + shortcut hint */
  if (!/Mac|iPhone|iPad/.test(navigator.platform || '')) $$('.search-trigger kbd').forEach(function(k){ k.textContent = 'Ctrl K'; });
  $$('.js-year').forEach(function(el){ el.textContent = new Date().getFullYear(); });

  /* Theme toggle */
  $$('[data-theme-toggle]').forEach(function(btn){
    btn.addEventListener('click', function(){
      var next = root.getAttribute('data-theme') === 'light' ? 'dark' : 'light';
      root.setAttribute('data-theme', next);
      try { localStorage.setItem('gh-theme', next); } catch(e){}
    });
  });

  /* Accent the last word of display titles */
  $$('[data-accent-last]').forEach(function(el){
    var t = el.textContent.trim(), i = t.lastIndexOf(' ');
    if (i < 1) return;
    el.textContent = t.slice(0, i + 1);
    var em = d.createElement('em'); em.textContent = t.slice(i + 1);
    el.appendChild(em);
  });

  /* Active nav link */
  var here = location.pathname.replace(/\/$/, '') || '/';
  $$('.nav-list a').forEach(function(a){
    try {
      var p = new URL(a.href, location.href).pathname.replace(/\/$/, '') || '/';
      if (p === here) a.classList.add('is-active');
    } catch(e){}
  });

  /* Mobile menu (clones the primary nav) */
  var toggle = $('.menu-toggle'), mm = $('#mobile-menu'), navList = $('#primary-nav');
  if (toggle && mm && navList) {
    $('.mobile-menu-links', mm).appendChild(navList.cloneNode(true)).removeAttribute('id');
    var setMenu = function(open){
      body.classList.toggle('nav-open', open);
      toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    };
    toggle.addEventListener('click', function(){ setMenu(!body.classList.contains('nav-open')); });
    $$('a', mm).forEach(function(a){ a.addEventListener('click', function(){ setMenu(false); }); });
    d.addEventListener('keydown', function(e){ if (e.key === 'Escape') setMenu(false); });
  }

  /* Search overlay (⌘K / Ctrl+K / "/") */
  var so = $('#search-overlay'), si = $('#search-input');
  if (so) {
    var openSearch = function(){ so.classList.add('open'); setTimeout(function(){ si && si.focus(); }, 60); };
    var closeSearch = function(){ so.classList.remove('open'); };
    $$('[data-search-open]').forEach(function(b){ b.addEventListener('click', openSearch); });
    $$('[data-search-close]').forEach(function(b){ b.addEventListener('click', closeSearch); });
    so.addEventListener('click', function(e){ if (e.target === so) closeSearch(); });
    d.addEventListener('keydown', function(e){
      var typing = /INPUT|TEXTAREA|SELECT/.test((e.target || {}).tagName || '') || e.target.isContentEditable;
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); openSearch(); }
      else if (e.key === '/' && !typing) { e.preventDefault(); openSearch(); }
      else if (e.key === 'Escape') closeSearch();
    });
  }

  /* Scroll reveal */
  var reveals = $$('.reveal');
  if ('IntersectionObserver' in window) {
    var ro = new IntersectionObserver(function(entries){
      entries.forEach(function(en){ if (en.isIntersecting) { en.target.classList.add('in'); ro.unobserve(en.target); } });
    }, { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
    reveals.forEach(function(el, i){ el.style.transitionDelay = (Math.min(i % 3, 2) * 80) + 'ms'; ro.observe(el); });
  } else { reveals.forEach(function(el){ el.classList.add('in'); }); }

  /* Empty listing */
  var grid = $('.post-grid');
  if (grid && !grid.children.length) {
    grid.innerHTML = '<div class="empty-state"><strong>Nothing here yet</strong>Try a different search or browse the latest stories.</div>';
  }

  /* Strip photo-credit prefixes from server-rendered snippets */
  $$('.card-snippet').forEach(function(el){
    var t = el.textContent.replace(/^photo by[\s\S]*?on\s+(pexels|unsplash|pixabay|freepik|shutterstock|istock(?:photo)?)\s*/i, '').trim();
    if (t) el.textContent = t;
  });

  /* Post images: drop Blogger's fixed size, load a sharper rendition.
     Small graphics (original under 400px wide) keep their natural size. */
  $$('.post-body img').forEach(function(im){
    var ow = parseInt(im.getAttribute('data-original-width') || '', 10);
    im.src = im.src.replace(/\/[swh]\d+(-[a-z0-9]+)*\/(?=[^\/]+$)/, '/w1600/').replace(/=[swh]\d+(-[a-z0-9]+)*$/, '=w1600');
    if (ow && ow < 400) im.classList.add('img-natural');
  });

  /* Avatar placeholder: show the author initial */
  $$('.byline .av-ph').forEach(function(ph){
    var n = ph.parentElement.querySelector('b') || ph.nextElementSibling;
    ph.textContent = (((n && n.textContent.trim()) || '•')[0]).toUpperCase();
  });

  /* Scroll-driven bits: header, progress, back-to-top (rAF-throttled) */
  var header = $('.header-bar'), bar = $('.progress'), toTop = $('.to-top'), postBody = $('.post-body');
  var ticking = false;
  var onScroll = function(){
    var y = window.pageYOffset;
    if (toTop) toTop.classList.toggle('show', y > 800);
    if (bar && postBody) {
      var r = postBody.getBoundingClientRect();
      var total = r.height - window.innerHeight * 0.6;
      var p = Math.min(1, Math.max(0, (-r.top + window.innerHeight * 0.3) / (total > 0 ? total : 1)));
      bar.style.transform = 'scaleX(' + p + ')';
    }
    ticking = false;
  };
  window.addEventListener('scroll', function(){ if (!ticking) { ticking = true; requestAnimationFrame(onScroll); } }, { passive: true });
  onScroll();

  /* ---------- Social icons (matched by link name or URL) ---------- */
  var SOCIAL = [
    ['facebook|fb.com',       '<path d="M14 8h3V4h-3a4 4 0 0 0-4 4v3H7v4h3v6h4v-6h3l1-4h-4V8z"/>'],
    ['twitter|//x.com|//www.x.com|^x$', '<path d="M4 4h4.5L20 20h-4.5zM20 4l-6.6 7.3M4 20l6.6-7.3"/>'],
    ['instagram',             '<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17.5 6.5h.01"/>'],
    ['youtube|youtu.be',      '<rect x="2" y="5" width="20" height="14" rx="4"/><path d="M10 9l5 3-5 3z"/>'],
    ['linkedin',              '<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M8 10v7M8 7v.01M12 17v-4a2 2 0 0 1 4 0v4M12 10v7"/>'],
    ['tiktok',                '<path d="M14 3v11.5a3.5 3.5 0 1 1-3.5-3.5M14 3c.5 2.5 2.5 4.5 5 4.5"/>'],
    ['pinterest',             '<circle cx="12" cy="12" r="9"/><path d="M10.5 20l2-8M10 13.6c.8 1.4 4.6 1.2 5.3-2.3C16 7.6 12.5 6 9.8 7.6 7.5 9 7.7 12 8.8 13"/>'],
    ['telegram|t.me',         '<path d="M21 4 3 11l6 2 2 6 3-4 5 4zM9 13l12-9"/>'],
    ['whatsapp|wa.me',        '<path d="M4 20l1.3-4A8 8 0 1 1 8 18.7z"/><path d="M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 .8a4 4 0 0 1-1.8-1.8l.8-1-1-2z"/>'],
    ['threads',               '<path d="M16.5 11.5c-.5-3-2.5-4.5-5-4.5-3 0-5 2.5-5 5.5S8.5 18 12 18c3 0 5.5-2 5.5-5 0-2.5-2-3.5-4.5-3.5-2 0-3.5 1-3.5 2.5s1.2 2.3 2.8 2.3c2.2 0 3.2-2 3.2-4.3V9"/>'],
    ['reddit',                '<circle cx="12" cy="14" r="6.5"/><path d="M9.5 15.5c1.4 1 3.6 1 5 0M9.5 13h.01M14.5 13h.01M12 7.5l1-4 4 1"/><circle cx="18" cy="4.8" r="1.3"/>'],
    ['github',                '<path d="M9 19c-4 1.5-4-2-6-2.5M15 21v-3.5c0-1 .1-1.4-.5-2 2.8-.3 5.5-1.4 5.5-6a4.6 4.6 0 0 0-1.3-3.2 4.3 4.3 0 0 0-.1-3.2s-1.1-.3-3.5 1.3a12 12 0 0 0-6.2 0C6.5 2.8 5.4 3.1 5.4 3.1a4.3 4.3 0 0 0-.1 3.2A4.6 4.6 0 0 0 4 9.5c0 4.6 2.7 5.7 5.5 6-.6.6-.6 1.2-.5 2V21"/>'],
    ['discord',               '<path d="M8 6.5C6 7 4.5 7.8 4 8.5 3 11 2.5 14 3 17c1.5 1 3 1.7 4.5 2l1-2M16 6.5c2 .5 3.5 1.3 4 2 1 2.5 1.5 5.5 1 8.5-1.5 1-3 1.7-4.5 2l-1-2M7.5 16.5c3 1.3 6 1.3 9 0M8.5 6.5c2.3-.6 4.7-.6 7 0"/><path d="M9.5 12.5h.01M14.5 12.5h.01"/>'],
    ['mailto:|email|e-mail|mail', '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/>'],
    ['rss|feed',              '<path d="M5 11a8 8 0 0 1 8 8M5 5a14 14 0 0 1 14 14"/><circle cx="6" cy="18" r="1"/>']
  ];
  $$('.social-link').forEach(function(a){
    var hay = ((a.getAttribute('aria-label') || '') + ' ' + (a.getAttribute('href') || '')).toLowerCase().trim();
    var name = (a.getAttribute('aria-label') || '').toLowerCase().trim();
    for (var i = 0; i < SOCIAL.length; i++) {
      var hit = SOCIAL[i][0].split('|').some(function(k){ return k.charAt(0) === '^' ? new RegExp(k).test(name) : hay.indexOf(k) > -1; });
      if (hit) {
        a.innerHTML = '<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">' + SOCIAL[i][1] + '</svg>';
        a.classList.add('has-icon');
        break;
      }
    }
    if (/^(mailto:|\/)/.test(a.getAttribute('href') || '')) a.removeAttribute('target');
  });

  /* ---------- Hide ad slots that have no gadget ---------- */
  $$('.ad-section').forEach(function(sec){ if (!sec.querySelector('.widget')) sec.classList.add('is-empty'); });

  /* ---------- Drop stray empty blocks left by pasted post HTML ---------- */
  $$('.post-body small > br:first-child').forEach(function(b){ b.remove(); });
  $$('.post-body p').forEach(function(p){
    if (!p.textContent.trim() && !p.querySelector('img,iframe,video,audio,table,hr')) p.remove();
  });

  /* ---------- Scale fixed-size ad banners down on narrow screens ---------- */
  var fitAds = function(){
    $$('.ad-section iframe').forEach(function(f){
      var w = parseInt(f.getAttribute('width'), 10), h = parseInt(f.getAttribute('height'), 10);
      if (!w || !h) return;
      var box = f.parentNode, avail = box ? box.clientWidth : 0;
      if (!avail) return;
      if (w <= avail) { f.style.cssText = ''; return; }
      var s = avail / w;
      f.style.cssText = 'display:block;max-width:none;width:' + w + 'px;height:' + h + 'px;transform-origin:top left;transform:scale(' + s + ');margin:0 ' + Math.round(-(w * (1 - s))) + 'px ' + Math.round(-(h * (1 - s))) + 'px 0;';
    });
  };
  fitAds();
  window.addEventListener('resize', fitAds);
  window.addEventListener('load', fitAds);
  setTimeout(fitAds, 1500);

  /* ---------- Hero slider (homepage) ---------- */
  var heroGrid = $('#hero-grid');
  if (heroGrid && window.fetch) (function(){
    var heroSection = heroGrid.closest('.hero');
    var cfg = $('.hero-config'), heroLabel = cfg ? cfg.textContent.trim() : '';
    var SLIDES = 4, SIDE = 3;
    var esc = function(v){ return String(v == null ? '' : v).replace(/[&<>"']/g, function(c){ return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
    var pad = function(n){ return (n < 10 ? '0' : '') + n; };
    var sized = function(u, w, h){
      if (!u) return '';
      return u.replace(/\/[swh]\d+(-[a-z0-9]+)*\/(?=[^\/]+$)/, '/w' + w + '-h' + h + '-c/').replace(/=[swh]\d+(-[a-z0-9]+)*$/, '=w' + w + '-h' + h + '-c').replace(/\/(default|mqdefault)\.jpg$/, '/hqdefault.jpg');
    };
    var fmt = function(dt){ return dt.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); };
    var labelUrl = function(l){ return '/search/label/' + encodeURIComponent(l); };
    var stripCredit = function(t){ return String(t || '').replace(/^photo by[\s\S]*?on\s+(pexels|unsplash|pixabay|freepik|shutterstock|istock(?:photo)?)\s*/i, '').trim(); };
    var parse = function(j){
      return ((j.feed && j.feed.entry) || []).map(function(e){
        var alt = (e.link || []).filter(function(l){ return l.rel === 'alternate'; })[0];
        if (!alt) return null;
        var html = (e.content && e.content.$t) || '';
        var img = e.media$thumbnail ? e.media$thumbnail.url : (html.match(/<img[^>]+src=["']([^"']+)["']/i) || [])[1] || '';
        var sum = ((e.summary && e.summary.$t) || '').replace(/\s+/g, ' ').trim();
        if (!sum && html) sum = html.replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();
        sum = stripCredit(sum);
        if (sum.length > 200) sum = sum.slice(0, 200).replace(/\s+\S*$/, '') + '…';
        return {
          t: e.title.$t, u: alt.href, sum: sum, date: new Date(e.published.$t),
          img: img,
          label: e.category && e.category[0] ? e.category[0].term : ''
        };
      }).filter(Boolean);
    };
    var feed = function(label, n){
      return fetch('/feeds/posts/default' + (label ? '/-/' + encodeURIComponent(label) : '') + '?alt=json&max-results=' + n)
        .then(function(r){ if (!r.ok) throw new Error(r.status); return r.json(); }).then(parse);
    };
    var arrow = function(d){ return '<svg class="ic" viewBox="0 0 24 24"><path d="' + (d < 0 ? 'M19 12H5M11 6l-6 6 6 6' : 'M5 12h14M13 6l6 6-6 6') + '"/></svg>'; };

    var render = function(slides, side){
      var slider = $('#hero-slider'), core = $('.slider-core', slider), sideWrap = $('.hero-side', heroGrid);
      core.classList.remove('skel');
      core.innerHTML = slides.map(function(p, i){
        return '<article class="slide' + (i ? '' : ' is-active') + '" role="group" aria-roledescription="slide" aria-label="' + (i + 1) + ' of ' + slides.length + '">' +
          '<a class="slide-media" href="' + esc(p.u) + '" tabindex="-1" aria-hidden="true">' +
            (p.img ? '<img src="' + esc(sized(p.img, 1600, 1000)) + '" alt="" decoding="async"' + (i ? ' loading="lazy"' : ' fetchpriority="high"') + '>' : '<span class="card-ph"></span>') +
          '</a>' +
          '<div class="slide-body">' +
            '<div class="slide-meta">' + (p.label ? '<a class="chip" href="' + esc(labelUrl(p.label)) + '">' + esc(p.label) + '</a>' : '') + '<time>' + esc(fmt(p.date)) + '</time></div>' +
            '<h2 class="slide-title"><a href="' + esc(p.u) + '">' + esc(p.t) + '</a></h2>' +
            (p.sum ? '<p class="slide-snippet">' + esc(p.sum) + '</p>' : '') +
            '<a class="btn btn-primary slide-cta" href="' + esc(p.u) + '">Read story<span class="btn-ico"><svg class="ic" viewBox="0 0 24 24"><path d="M7 17 17 7M8 7h9v9"/></svg></span></a>' +
          '</div>' +
        '</article>';
      }).join('') + (slides.length > 1 ?
        '<div class="slider-bars">' + slides.map(function(p, i){ return '<button type="button" aria-label="Go to slide ' + (i + 1) + '"><i></i></button>'; }).join('') + '</div>' +
        '<div class="slider-ui"><span class="slider-count"><b>01</b> / ' + pad(slides.length) + '</span>' +
          '<button type="button" class="slider-btn" data-dir="-1" aria-label="Previous slide">' + arrow(-1) + '</button>' +
          '<button type="button" class="slider-btn" data-dir="1" aria-label="Next slide">' + arrow(1) + '</button></div>' : '');

      if (side.length) {
        sideWrap.innerHTML = side.map(function(p){
          return '<article class="side-post shell"><div class="core">' +
            '<a class="side-thumb" href="' + esc(p.u) + '" tabindex="-1" aria-hidden="true">' +
              (p.img ? '<img src="' + esc(sized(p.img, 480, 400)) + '" alt="" loading="lazy" decoding="async">' : '<span class="card-ph"></span>') +
            '</a>' +
            '<div class="side-body">' +
              '<div class="side-meta">' + (p.label ? '<a class="chip" href="' + esc(labelUrl(p.label)) + '">' + esc(p.label) + '</a>' : '') + '<time>' + esc(fmt(p.date)) + '</time></div>' +
              '<h3 class="side-title"><a href="' + esc(p.u) + '">' + esc(p.t) + '</a></h3>' +
            '</div>' +
          '</div></article>';
        }).join('');
      } else {
        sideWrap.remove();
        heroGrid.classList.add('is-solo');
      }

      if (slides.length < 2) return;
      var items = $$('.slide', core), bars = $$('.slider-bars button', core), count = $('.slider-count b', core), cur = 0;
      var go = function(n){
        n = (n + items.length) % items.length;
        items.forEach(function(el, i){ var on = i === n; el.classList.toggle('is-active', on); el.inert = !on; el.setAttribute('aria-hidden', on ? 'false' : 'true'); });
        bars.forEach(function(b, i){ b.classList.remove('is-active'); b.classList.toggle('is-done', i < n); b.setAttribute('aria-current', i === n ? 'true' : 'false'); });
        void bars[n].offsetWidth;
        bars[n].classList.add('is-active');
        count.textContent = pad(n + 1);
        cur = n;
      };
      bars.forEach(function(b, i){
        b.addEventListener('click', function(){ go(i); });
        b.firstChild.addEventListener('animationend', function(){ if (b.classList.contains('is-active')) go(cur + 1); });
      });
      $$('.slider-btn', core).forEach(function(b){ b.addEventListener('click', function(){ go(cur + Number(b.getAttribute('data-dir'))); }); });
      var pause = function(on){ slider.classList.toggle('is-paused', on); };
      slider.addEventListener('mouseenter', function(){ pause(true); });
      slider.addEventListener('mouseleave', function(){ pause(slider.contains(d.activeElement)); });
      slider.addEventListener('focusin', function(){ pause(true); });
      slider.addEventListener('focusout', function(e){ if (!slider.contains(e.relatedTarget)) pause(false); });
      slider.addEventListener('keydown', function(e){
        if (e.key === 'ArrowRight') { e.preventDefault(); go(cur + 1); }
        else if (e.key === 'ArrowLeft') { e.preventDefault(); go(cur - 1); }
      });
      var sx = null, swiped = false;
      core.addEventListener('dragstart', function(e){ e.preventDefault(); });
      core.addEventListener('pointerdown', function(e){ sx = e.clientX; swiped = false; });
      core.addEventListener('pointercancel', function(){ sx = null; });
      core.addEventListener('pointerup', function(e){
        if (sx === null) return;
        var dx = e.clientX - sx; sx = null;
        if (Math.abs(dx) > 50) { swiped = true; go(cur + (dx < 0 ? 1 : -1)); }
      });
      core.addEventListener('click', function(e){ if (swiped) { e.preventDefault(); e.stopPropagation(); swiped = false; } }, true);
      go(0);
    };

    Promise.all([
      heroLabel ? feed(heroLabel, SLIDES).catch(function(){ return []; }) : Promise.resolve([]),
      feed('', SLIDES + SIDE + 4)
    ]).then(function(res){
      var picked = res[0], latest = res[1], slides, side;
      if (picked.length) {
        slides = picked.slice(0, SLIDES);
        var used = slides.map(function(p){ return p.u; });
        side = latest.filter(function(p){ return used.indexOf(p.u) < 0; }).slice(0, SIDE);
      } else if (latest.length >= SLIDES + SIDE) {
        slides = latest.slice(0, SLIDES); side = latest.slice(SLIDES, SLIDES + SIDE);
      } else if (latest.length > 1) {
        var n = Math.min(SIDE, latest.length - 1);
        slides = latest.slice(0, latest.length - n); side = latest.slice(latest.length - n);
      } else { slides = latest; side = []; }
      if (!slides.length) { heroSection.remove(); return; }
      render(slides, side);
    }).catch(function(){ heroSection.remove(); });
  })();

  /* ---------- Post page only ---------- */
  if (!postBody || !body.classList.contains('view-post')) return;

  /* Reading time */
  var words = (postBody.innerText || postBody.textContent || '').trim().split(/\s+/).length;
  $$('.js-readtime').forEach(function(el){ el.textContent = Math.max(1, Math.round(words / 225)) + ' min read'; });

  /* Table of contents + scroll spy */
  var tocCard = $('#toc-card'), tocList = $('#toc-list');
  var heads = $$('h2, h3', postBody).filter(function(h){ return h.textContent.trim(); });
  if (tocCard && tocList && heads.length >= 2) {
    var used = {};
    heads.forEach(function(h, i){
      if (!h.id) {
        var s = h.textContent.toLowerCase().trim().replace(/[\s!-\/:-@\[-`{-~]+/g, '-').replace(/^-+|-+$/g, '') || ('section-' + i);
        while (used[s]) s += '-' + i;
        h.id = s;
      }
      used[h.id] = 1;
      var li = d.createElement('li'); li.className = 'lvl-' + h.tagName.charAt(1);
      var a = d.createElement('a'); a.href = '#' + h.id; a.textContent = h.textContent.trim();
      li.appendChild(a); tocList.appendChild(li);
    });
    tocCard.hidden = false;
    var links = $$('a', tocList);
    if ('IntersectionObserver' in window) {
      var spy = new IntersectionObserver(function(entries){
        entries.forEach(function(en){
          if (!en.isIntersecting) return;
          links.forEach(function(l){ l.classList.toggle('active', l.getAttribute('href') === '#' + en.target.id); });
        });
      }, { rootMargin: '-100px 0px -70% 0px' });
      heads.forEach(function(h){ spy.observe(h); });
    }
  }

  /* Share */
  var url = encodeURIComponent(location.href.split('?')[0].split('#')[0]);
  var title = encodeURIComponent(($('.post-title') || {}).textContent ? $('.post-title').textContent.trim() : d.title);
  var shareMap = {
    x:  'https://twitter.com/intent/tweet?url=' + url + '&text=' + title,
    fb: 'https://www.facebook.com/sharer/sharer.php?u=' + url,
    'in': 'https://www.linkedin.com/sharing/share-offsite/?url=' + url,
    wa: 'https://wa.me/?text=' + title + '%20' + url
  };
  $$('[data-share]').forEach(function(a){ a.href = shareMap[a.getAttribute('data-share')] || '#'; });
  $$('[data-copy]').forEach(function(b){
    b.addEventListener('click', function(){
      var done = function(){ b.classList.add('copied'); setTimeout(function(){ b.classList.remove('copied'); }, 1600); };
      var link = decodeURIComponent(url);
      if (navigator.clipboard) navigator.clipboard.writeText(link).then(done, function(){});
      else { var t = d.createElement('textarea'); t.value = link; body.appendChild(t); t.select(); try { d.execCommand('copy'); done(); } catch(e){} t.remove(); }
    });
  });

  /* Related posts (same first label, via JSON feed) */
  var rel = $('#related');
  if (rel) {
    var src = $('.related-src', rel), label = src && src.getAttribute('data-label');
    var relGrid = $('.related-grid', rel);
    var path = function(u){ try { return new URL(u, location.href).pathname; } catch(e){ return u; } };
    var current = path(rel.getAttribute('data-url') || location.href);
    if (!label || !window.fetch) { rel.remove(); }
    else {
      fetch('/feeds/posts/default/-/' + encodeURIComponent(label) + '?alt=json&max-results=8')
        .then(function(r){ return r.json(); })
        .then(function(j){
          var items = ((j.feed && j.feed.entry) || []).map(function(e){
            var alt = (e.link || []).filter(function(l){ return l.rel === 'alternate'; })[0];
            var html = (e.content && e.content.$t) || '';
            var thumb = e.media$thumbnail ? e.media$thumbnail.url : (html.match(/<img[^>]+src=["']([^"']+)["']/i) || [])[1] || '';
            var img = thumb ? thumb.replace(/\/[swh]\d+(-[a-z0-9]+)*\/(?=[^\/]+$)/, '/w720-h450-c/').replace(/=[swh]\d+(-[a-z0-9]+)*$/, '=w720-h450-c') : '';
            return alt ? { t: e.title.$t, h: alt.href, i: img, d: new Date(e.published.$t) } : null;
          }).filter(function(x){ return x && path(x.h) !== current; }).slice(0, 3);
          if (!items.length) { rel.remove(); return; }
          relGrid.innerHTML = '';
          items.forEach(function(it){
            var a = d.createElement('a'); a.className = 'rel-item'; a.href = it.h;
            var m = d.createElement('span'); m.className = 'rel-media';
            if (it.i) { var im = d.createElement('img'); im.src = it.i; im.alt = it.t; im.loading = 'lazy'; m.appendChild(im); }
            var b = d.createElement('b'); b.textContent = it.t;
            var s = d.createElement('small'); s.textContent = it.d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
            a.appendChild(m); a.appendChild(s); a.appendChild(b); relGrid.appendChild(a);
          });
        })
        .catch(function(){ rel.remove(); });
    }
  }
})();
